outputs = ['ydfkc', 'zywh', 'ijzbwgw', 'igwgwxdz', 'fgjj']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find first difference
    pos = -1
    for j in range(min(len(inp), len(outp))):
        if inp[j] != outp[j]:
            pos = j
            break

    if pos == -1:
        if len(inp) != len(outp):
            pos = min(len(inp), len(outp))

    if pos != -1:
        if pos < len(inp) and pos < len(outp):
            print(f"  First difference at position {pos}: '{inp[pos]}' -> '{outp[pos]}'")
        elif pos >= len(outp):
            print(f"  String shortened at position {pos}")
        elif pos >= len(inp):
            print(f"  String lengthened at position {pos}")
    else:
        print("  Strings are identical")
    print()

